POSITIVE = ('\u6ee1\u610f', '\u63a8\u8350', '\u5f88\u597d')
NEGATIVE = ('\u5931\u671b', '\u6162', '\u5dee')


def sentiment(text):
    if any(word in text for word in NEGATIVE):
        return 'negative'
    if any(word in text for word in POSITIVE):
        return 'positive'
    return 'negative'

